import{_ as s,l as i,o as e,c as l,v as t,p as n,x as r,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"上下文切换","description":"","frontmatter":{"title":"上下文切换","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/context-switch.md","filePath":"cs/context-switch.md","lastUpdated":1789023840000}'),h={name:"cs/context-switch.md"};function E(A,a,B,_,m,f){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="上下文切换" tabindex="-1">上下文切换 <a class="header-anchor" href="#上下文切换" aria-label="Permalink to &quot;上下文切换&quot;">​</a></h1><div class="epigraph"><p>切换的代价是保存与恢复寄存器、切换内存映像，以及刷新各种缓存；它不是免费的。</p><footer>—— 据 Silberschatz et al., Operating System Concepts 整理</footer></div><p><a href="/cs/clone-flags">上一课</a>给出多条可运行的控制流。<a href="/cs/exception-interrupt-entry">异常与中断入口</a>已经会在陷入时保存 PC。缺口是：内核不仅要进一次入口，还要把 CPU <strong>交给另一条线程</strong>，再从那条线程的入口看起来像从未离开。本课只钉保存什么、换什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>时钟中断或线程主动阻塞时，当前寄存器仍是旧线程的。若不写入控制块就去跑别人，回来时栈指针已经错。跨进程时还要换页表根，否则下一线程用的虚地址会落到旧页上。缺口不是再讲特权环，而是一次<strong>上下文切换</strong>：内核栈上的陷入帧 + PCB/TCC 里的其余状态 + 可选的地址空间。</p><p>本课不解释为何选中某一线程，那是调度；也不把系统调用参数拷贝写完，那是下一课路径。</p><p><span class="marginnote">切换计入内核时间。流水线与 TLB、Cache 的热度都会冷掉，所以「可运行线程很多」并不线性加速。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在内核态：保存通用寄存器与 PC 到当前线程控制块；选中下一线程后，若地址空间不同则装入新的页表根并处理 <a href="/cs/tlb-translate">TLB</a>；切换内核栈指针；恢复目标寄存器，返回用户态或留在内核（内核线程）。同进程线程可跳过换根。</p>',9)),(e(),n(d,null,{default:r(()=>[p(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20IRQ%5B%22%E4%B8%AD%E6%96%AD%E6%88%96%E9%98%BB%E5%A1%9E%22%5D%20--%3E%20SAVE%5B%22%E4%BF%9D%E5%AD%98%E5%BD%93%E5%89%8D%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20SAVE%20--%3E%20PICK%5B%22%E9%80%89%E4%B8%8B%E4%B8%80%E7%BA%BF%E7%A8%8B%22%5D%0A%20%20PICK%20--%3E%20AS%5B%22%E5%BF%85%E8%A6%81%E6%97%B6%E6%8D%A2%E9%A1%B5%E8%A1%A8%E6%A0%B9%22%5D%0A%20%20AS%20--%3E%20REST%5B%22%E6%81%A2%E5%A4%8D%E5%B9%B6%E8%BF%94%E5%9B%9E%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>硬件上下文（FPU/向量）可以懒保存：直到真正被另一线程使用再换，本课承认有这笔账，不写具体 ABI。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对用户线程，切换必须发生在内核态：用户不能自己改页表根。看起来像「这条线程睡着、那条醒来」，其实是同一 CPU 换了一套映像。<a href="/cs/pipeline-exception">流水线异常</a>要求陷入时精确；切换复用那套保存下来的架构状态，不另造一套寄存器含义。</p><p>阻塞与抢占都走同一条保存路径。区别只在于谁引发陷入：<code>sleep</code> 是自愿，时钟是非自愿。调度指标下一课才出现。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入用户级无内核切换的协程实现细节，不把 NUMA 亲和与 CPU 热插拔写进主干。也不把「一次切换多少微秒」当成定律：取决于寄存器组大小与缓存。安全课的隔离会关心「有没有漏存」，本课假定保存是完整的。</p><p>后课默认：CPU 上任何时刻至多一条线程的用户寄存器是活的；其余在控制块里。用户如何主动进入这条路径请求服务，下一课讲系统调用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>上下文切换保存寄存器，必要时换页表根，再恢复另一线程。</li><li>同进程可免换根；跨进程要处理 TLB。</li><li>选谁运行是调度的缺口；怎么陷入请求是系统调用的缺口。</li><li>出处：Silberschatz et al., <em>OSC</em>；Tanenbaum and Bos, <em>MOS</em>。</li></ul>',9))])}const S=s(h,[["render",E]]);export{P as __pageData,S as default};
